/* ==========================================================================
   Café Lumière - Design System & Stylesheet
   Warm Earth Tones, Refined Typography, Serene Atmosphere
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=Noto+Serif+JP:wght@300;400;500;600&family=Noto+Sans+JP:wght@300;400;500&display=swap');

:root {
  /* Color Palette */
  --color-bg: #FAF7F2;
  --color-surface: #FFFFFF;
  --color-surface-soft: #F4EFEA;
  --color-surface-hover: #ECE4DA;
  --color-primary: #8C6239;
  --color-primary-dark: #6E4924;
  --color-primary-light: #C4A482;
  --color-accent: #B25D38;
  --color-text-main: #2D251E;
  --color-text-muted: #6B5E53;
  --color-text-light: #968677;
  --color-border: #E8DFD5;
  --color-border-light: #F0E9E1;

  /* Typography */
  --font-serif: 'Noto Serif JP', 'Cormorant Garamond', 'Yu Mincho', serif;
  --font-en-serif: 'Cormorant Garamond', 'Noto Serif JP', serif;
  --font-sans: 'Noto Sans JP', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  /* Shadows */
  --shadow-sm: 0 2px 8px rgba(45, 37, 30, 0.04);
  --shadow-md: 0 8px 24px rgba(45, 37, 30, 0.08);
  --shadow-lg: 0 16px 40px rgba(45, 37, 30, 0.12);
  --shadow-modal: 0 24px 64px rgba(25, 18, 12, 0.28);

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-normal: 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Base Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-sans);
  line-height: 1.75;
  letter-spacing: 0.02em;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

/* Layout Wrapper */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* Header & Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(250, 247, 242, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  transition: background-color var(--transition-normal), box-shadow var(--transition-normal);
}

.nav {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.nav-logo {
  font-family: var(--font-en-serif);
  font-size: 1.6rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--color-text-main);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: opacity var(--transition-fast);
}

.nav-logo:hover {
  opacity: 0.8;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-link {
  text-decoration: none;
  color: var(--color-text-muted);
  font-size: 0.95rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  transition: color var(--transition-fast);
  position: relative;
  padding: 0.25rem 0;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1.5px;
  background-color: var(--color-primary);
  transition: width var(--transition-fast);
}

.nav-link:hover {
  color: var(--color-primary);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-reserve-btn {
  background-color: var(--color-primary);
  color: #FFFFFF;
  padding: 0.6rem 1.25rem;
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  transition: all var(--transition-fast);
  box-shadow: 0 4px 12px rgba(140, 98, 57, 0.25);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.nav-reserve-btn:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(140, 98, 57, 0.35);
}

/* Hero Section */
.hero-section {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1920&q=80');
  background-size: cover;
  background-position: center 40%;
  color: #FFFFFF;
  padding: 4rem 1.5rem;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(25, 18, 12, 0.45) 0%,
    rgba(25, 18, 12, 0.65) 60%,
    rgba(25, 18, 12, 0.85) 100%
  );
  backdrop-filter: blur(1px);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero-tagline {
  font-family: var(--font-en-serif);
  font-size: 1.15rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #E6D2BC;
  margin-bottom: 1rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  font-weight: 500;
  line-height: 1.35;
  letter-spacing: 0.08em;
  margin-bottom: 1.5rem;
  text-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.hero-desc {
  font-size: clamp(1rem, 1.8vw, 1.15rem);
  color: #F3EDE7;
  max-width: 620px;
  margin-bottom: 2.5rem;
  line-height: 1.9;
  letter-spacing: 0.03em;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  flex-wrap: wrap;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #FFFFFF;
  padding: 0.85rem 2rem;
  border-radius: var(--radius-full);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  transition: all var(--transition-fast);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  text-decoration: none;
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-2px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.25);
}

.btn-secondary {
  background-color: rgba(255, 255, 255, 0.15);
  color: #FFFFFF;
  padding: 0.85rem 2rem;
  border-radius: var(--radius-full);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.4);
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  text-decoration: none;
}

.btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.25);
  border-color: #FFFFFF;
  transform: translateY(-2px);
}

/* General Section Structure */
.section {
  padding: 6rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
}

.section-subtitle {
  display: inline-block;
  font-family: var(--font-en-serif);
  font-size: 1.05rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  font-weight: 500;
  color: var(--color-text-main);
  letter-spacing: 0.06em;
  margin-bottom: 1rem;
}

.section-desc {
  font-size: 1rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.8;
}

/* Concept Cards */
.concept-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.concept-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 2.5rem 2rem;
  text-align: center;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary-light);
}

.concept-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  background-color: var(--color-surface-soft);
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.concept-card:hover .concept-icon {
  background-color: #EBDCCF;
  transform: scale(1.08);
}

.concept-title {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 500;
  color: var(--color-text-main);
  margin-bottom: 1rem;
  letter-spacing: 0.04em;
}

.concept-text {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.85;
}

/* Menu Tabs */
.menu-tabs {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.menu-tab-btn {
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-full);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.menu-tab-btn:hover {
  color: var(--color-primary);
  border-color: var(--color-primary-light);
  background-color: var(--color-surface-soft);
}

.menu-tab-btn-active {
  background-color: var(--color-primary);
  color: #FFFFFF;
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(140, 98, 57, 0.25);
}

.menu-tab-btn-active:hover {
  background-color: var(--color-primary-dark);
  color: #FFFFFF;
}

/* Menu Grid & Cards */
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 2rem;
}

.menu-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal), border-color var(--transition-normal);
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary-light);
}

.menu-img-wrap {
  position: relative;
  width: 100%;
  padding-top: 66.66%;
  overflow: hidden;
  background-color: var(--color-surface-soft);
}

.menu-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.menu-card:hover .menu-img {
  transform: scale(1.05);
}

.menu-badge {
  position: absolute;
  top: 0.85rem;
  right: 0.85rem;
  background-color: var(--color-accent);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
  z-index: 2;
}

.menu-card-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.menu-title-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.25rem;
}

.menu-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 500;
  color: var(--color-text-main);
  letter-spacing: 0.02em;
}

.menu-price {
  font-family: var(--font-en-serif);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  white-space: nowrap;
}

.menu-name-en {
  font-family: var(--font-en-serif);
  font-size: 0.85rem;
  color: var(--color-text-light);
  font-style: italic;
  margin-bottom: 0.75rem;
}

.menu-card-desc {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-top: auto;
}

/* Access & Store Info */
.access-container {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 3rem;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 3rem;
  box-shadow: var(--shadow-sm);
}

.access-info-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.access-table {
  width: 100%;
  border-collapse: collapse;
}

.access-row {
  border-bottom: 1px solid var(--color-border-light);
}

.access-row:last-child {
  border-bottom: none;
}

.access-label {
  padding: 1rem 0;
  width: 110px;
  font-weight: 500;
  color: var(--color-text-main);
  font-size: 0.95rem;
  vertical-align: top;
}

.access-value {
  padding: 1rem 0 1rem 1rem;
  color: var(--color-text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

.facility-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.facility-tag {
  background-color: var(--color-surface-soft);
  color: var(--color-primary-dark);
  font-size: 0.8rem;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border);
}

.access-map-col {
  display: flex;
  flex-direction: column;
}

.map-card {
  height: 100%;
  display: flex;
  flex-direction: column;
  background-color: var(--color-surface-soft);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.map-visual {
  width: 100%;
  min-height: 240px;
  flex-grow: 1;
  border: none;
  background-color: #E6DFD5;
}

.map-station-info {
  padding: 1.25rem 1.5rem;
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  font-size: 0.9rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Reservation Modal */
.reservation-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background-color: rgba(25, 18, 12, 0.65);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  animation: fadeIn 0.25s ease-out;
}

.reservation-modal {
  background-color: var(--color-surface);
  width: 100%;
  max-width: 540px;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-modal);
  padding: 2.5rem;
  position: relative;
  animation: modalSlideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-border);
}

.modal-title {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  font-weight: 500;
  color: var(--color-text-main);
  letter-spacing: 0.03em;
}

.modal-close-btn {
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-text-light);
  padding: 0.25rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.modal-close-btn:hover {
  color: var(--color-text-main);
  background-color: var(--color-surface-soft);
}

.reservation-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-main);
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-surface);
  font-size: 0.95rem;
  color: var(--color-text-main);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(140, 98, 57, 0.15);
}

.form-textarea {
  resize: vertical;
  min-height: 90px;
}

.modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1rem;
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--color-border-light);
}

.success-message {
  text-align: center;
  padding: 2.5rem 1rem;
}

/* Footer */
.footer {
  margin-top: auto;
  background-color: #231B15;
  color: #D6CBC1;
  padding: 4rem 1.5rem 2.5rem;
  border-top: 1px solid #362B22;
}

.footer-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  text-align: center;
}

.footer-copy {
  font-size: 0.85rem;
  color: #8C7F73;
  letter-spacing: 0.04em;
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modalSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Responsive Breakpoints */
@media (max-width: 900px) {
  .access-container {
    grid-template-columns: 1fr;
    gap: 2.5rem;
    padding: 2rem 1.5rem;
  }

  .map-visual {
    min-height: 220px;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 0.85rem 1rem;
  }

  .nav-links {
    gap: 1rem;
  }

  .nav-link {
    font-size: 0.88rem;
  }

  .section {
    padding: 4rem 1.25rem;
  }

  .hero-section {
    min-height: 75vh;
    padding: 3rem 1.25rem;
  }

  .reservation-modal {
    padding: 1.75rem 1.25rem;
  }

  .access-label {
    width: 90px;
  }
}

@media (max-width: 480px) {
  .nav-links {
    display: none;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .btn-primary,
  .btn-secondary {
    width: 100%;
  }

  .modal-actions {
    flex-direction: column-reverse;
  }

  .modal-actions button {
    width: 100%;
  }
}

export type MenuCategoryId = 'all' | 'coffee' | 'drink' | 'sweets' | 'food';

export interface MenuItem {
  id: string;
  name: string;
  nameEn: string;
  category: 'coffee' | 'drink' | 'sweets' | 'food';
  price: number;
  description: string;
  imageUrl: string;
  isRecommended?: boolean;
}

export interface MenuCategory {
  id: MenuCategoryId;
  label: string;
}

export interface ConceptItem {
  id: string;
  iconName: 'Coffee' | 'Sparkles' | 'Clock';
  title: string;
  description: string;
}

export interface StoreInfo {
  name: string;
  catchphrase: string;
  address: string;
  nearestStation: string;
  walkTime: string;
  tel: string;
  openHours: string;
  regularHoliday: string;
  seats: string;
  facilities: string[];
  mapEmbedUrl: string;
}

export interface ReservationFormValues {
  name: string;
  date: string;
  time: string;
  guests: number;
  notes: string;
}
